// skill-release.json and engine.manifest.json are generated by
// scripts/manifest.mjs. They must be current, deterministic, hash the engine
// (not the customer directory) and name exactly the fork-editable surface.
import test from 'node:test';
import assert from 'node:assert/strict';
import { cpSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { read, exists, walk } from './helpers/scan.mjs';
import { withTmp } from './helpers/tmp.mjs';
import {
  buildRelease, buildManifest, writeManifests, checkManifests, compareManifest, treeDigest, FORK_EDITABLE, NPM_NEVER_PACKED,
} from '../scripts/manifest.mjs';

const ROOT = resolve(new URL('..', import.meta.url).pathname);
const release = JSON.parse(read('skill-release.json'));
const manifest = JSON.parse(read('engine.manifest.json'));
const pkg = JSON.parse(read('package.json'));
const DIGEST = /^sha256:[0-9a-f]{64}$/;

test('skill-release.json has the release shape of VISION §3', () => {
  assert.equal(release.name, pkg.name);
  assert.equal(release.version, pkg.version);
  assert.equal(typeof release.schema_versions, 'object');
  for (const [k, v] of Object.entries(release.schema_versions)) assert.match(v, new RegExp(`^dotfield\\.${k.replace(/[-.]/g, '[-.]')}/\\d+$`));
  assert.equal(release.rule_catalog_version, '1');
  assert.equal(release.three_revision, '180');
  assert.equal(release.min_node, '22.13');
  assert.match(release.digests.lib, DIGEST);
  assert.match(release.digests.schemas, DIGEST);
  assert.deepEqual(release.fork_editable, FORK_EDITABLE);
});

test('fork_editable names the root pointers, the templates/ folder, package name/description and the release name — nothing else', () => {
  assert.deepEqual(release.fork_editable, ['README.md', 'AGENTS.md', 'templates/', 'package.json#name', 'package.json#description', 'skill-release.json#name']);
});

test('engine.manifest.json hashes every engine file and no customer file', () => {
  assert.equal(manifest.algorithm, 'sha256');
  assert.equal(manifest.engine_version, pkg.version);
  const paths = Object.keys(manifest.files);
  assert.equal(paths.length, manifest.file_count);
  for (const [p, entry] of Object.entries(manifest.files)) {
    assert.match(entry.digest, DIGEST, p);
    assert.ok(!p.startsWith('center/'), `customer file hashed: ${p}`);
    assert.ok(!p.startsWith('data/') && !p.startsWith('.dotfield/') && !p.startsWith('node_modules/') && !p.startsWith('vendor/three/'), p);
    assert.ok(!p.endsWith('.generated.css'), p);
  }
  for (const must of ['VISION.md', 'package.json', '.gitignore', '.gitattributes', 'references/BUILD_CONTRACT.md', 'scripts/manifest.mjs', 'GOVERNANCE.md', 'CLAUDE.md', 'LICENSE', '.mcp.json', '.claude/skills/dotfield/SKILL.md', 'skill-release.json']) {
    assert.ok(manifest.files[must], `engine file not hashed: ${must}`);
  }
  for (const editable of ['README.md', 'AGENTS.md', 'engine.manifest.json']) assert.equal(manifest.files[editable], undefined, `${editable} must not be hashed whole`);
  assert.deepEqual(manifest.files['package.json'].normalized, ['name', 'description']);
  assert.deepEqual(manifest.files['skill-release.json'].normalized, ['name']);
  for (const rel of walk('lib')) assert.ok(manifest.files[rel], `lib file not hashed: ${rel}`);
  for (const rel of walk('schemas')) assert.ok(manifest.files[rel], `schema not hashed: ${rel}`);
});

test('both generated files are current (node scripts/manifest.mjs --check passes)', () => {
  const result = checkManifests(ROOT);
  assert.deepEqual(result.diffs, [], 'run: node scripts/manifest.mjs');
  assert.ok(result.ok);
});

test('the generator is deterministic and carries no timestamp', () => {
  const a = JSON.stringify(buildRelease(ROOT));
  const b = JSON.stringify(buildRelease(ROOT));
  assert.equal(a, b);
  assert.equal(JSON.stringify(buildManifest(ROOT)), JSON.stringify(buildManifest(ROOT)));
  assert.ok(!/generated_at|timestamp/.test(read('engine.manifest.json')));
  assert.equal(treeDigest(ROOT, 'lib'), release.digests.lib);
  assert.equal(treeDigest(ROOT, 'schemas'), release.digests.schemas);
});

test('a fork may rename itself without changing the manifest; an engine edit changes it', async () => {
  await withTmp(async (dir) => {
    for (const f of ['package.json', 'VISION.md', '.gitignore', 'README.md', 'AGENTS.md']) cpSync(resolve(ROOT, f), resolve(dir, f));
    mkdirSync(resolve(dir, 'lib'), { recursive: true });
    mkdirSync(resolve(dir, 'schemas'), { recursive: true });
    mkdirSync(resolve(dir, 'center'), { recursive: true });
    writeFileSync(resolve(dir, 'lib/x.mjs'), 'export const x = 1;\n');
    writeFileSync(resolve(dir, 'center/center.config.json'), '{"name":"c"}\n');
    const first = writeManifests(dir);
    assert.ok(checkManifests(dir).ok);

    const forked = JSON.parse(readFileSync(resolve(dir, 'package.json'), 'utf8'));
    forked.name = 'hall-lab-center';
    forked.description = 'A fork.';
    writeFileSync(resolve(dir, 'package.json'), `${JSON.stringify(forked, null, 2)}\n`);
    writeFileSync(resolve(dir, 'README.md'), '# Hall Lab\n');
    writeFileSync(resolve(dir, 'center/center.config.json'), '{"name":"hall"}\n');
    const rel = JSON.parse(readFileSync(resolve(dir, 'skill-release.json'), 'utf8'));
    rel.name = 'hall-lab-center';
    writeFileSync(resolve(dir, 'skill-release.json'), `${JSON.stringify(rel, null, 2)}\n`);
    const afterFork = compareManifest(dir);
    assert.deepEqual(afterFork, { ok: true, changed: [], missing: [], added: [] }, 'renaming the fork and editing center/ is not an engine change');
    assert.equal(buildRelease(dir).name, 'hall-lab-center', 'the release keeps the fork name');

    writeFileSync(resolve(dir, 'lib/x.mjs'), 'export const x = 2;\n');
    const afterEdit = compareManifest(dir);
    assert.deepEqual(afterEdit.changed, ['lib/x.mjs']);
    assert.notEqual(buildRelease(dir).digests.lib, first.release.digests.lib, 'an engine edit moves the lib digest');
    writeFileSync(resolve(dir, 'lib/y.mjs'), 'export const y = 1;\n');
    assert.deepEqual(compareManifest(dir).added, ['lib/y.mjs']);
  });
});

test('.mcp.json and .claude/launch.json are relative to the fork root', () => {
  const mcp = JSON.parse(read('.mcp.json'));
  assert.deepEqual(mcp.mcpServers.dotfield, { command: 'node', args: ['mcp/stdio.mjs'] });
  const launch = JSON.parse(read('.claude/launch.json'));
  assert.equal(launch.version, '0.0.1');
  assert.deepEqual(launch.configurations[0], { name: 'dotfield', runtimeExecutable: 'node', runtimeArgs: ['server/serve.mjs'], port: 4100 });
  assert.ok(exists('.claude/skills/dotfield/SKILL.md'));
});

test('an engine installed through npm or npx is not "modified" by the files npm never packs; any other absent file still is', () => {
  const known = manifest;
  const probe = { ...known, files: { ...known.files, '.npmrc': { digest: `sha256:${'0'.repeat(64)}` }, 'lib/ghost.mjs': { digest: `sha256:${'0'.repeat(64)}` } } };
  const cmp = compareManifest(ROOT, probe);
  assert.deepEqual(cmp.missing, ['lib/ghost.mjs']);
  for (const rel of ['.gitignore', 'package-lock.json']) assert.ok(NPM_NEVER_PACKED.has(rel), rel);
});
